"""Test script to verify _unregister_lookup clears the cache."""
import functools
import inspect

def subclasses(cls):
    yield cls
    for subclass in cls.__subclasses__():
        yield from subclasses(subclass)

# Simple implementation of RegisterLookupMixin
class RegisterLookupMixin:
    @classmethod
    def _get_lookup(cls, lookup_name):
        return cls.get_lookups().get(lookup_name, None)

    @classmethod
    @functools.lru_cache(maxsize=None)
    def get_lookups(cls):
        class_lookups = [
            parent.__dict__.get("class_lookups", {}) for parent in inspect.getmro(cls)
        ]
        return cls.merge_dicts(class_lookups)

    @staticmethod
    def merge_dicts(dicts):
        merged = {}
        for d in reversed(dicts):
            merged.update(d)
        return merged

    @classmethod
    def _clear_cached_lookups(cls):
        for subclass in subclasses(cls):
            subclass.get_lookups.cache_clear()

    @classmethod
    def register_lookup(cls, lookup, lookup_name=None):
        if lookup_name is None:
            lookup_name = lookup.lookup_name
        if "class_lookups" not in cls.__dict__:
            cls.class_lookups = {}
        cls.class_lookups[lookup_name] = lookup
        cls._clear_cached_lookups()
        return lookup

    @classmethod
    def _unregister_lookup_buggy(cls, lookup, lookup_name=None):
        """Buggy version without cache clearing."""
        if lookup_name is None:
            lookup_name = lookup.lookup_name
        del cls.class_lookups[lookup_name]

    @classmethod
    def _unregister_lookup_fixed(cls, lookup, lookup_name=None):
        """Fixed version with cache clearing."""
        if lookup_name is None:
            lookup_name = lookup.lookup_name
        del cls.class_lookups[lookup_name]
        cls._clear_cached_lookups()


# Create a test lookup class 
class DummyLookup:
    lookup_name = 'test_lookup'


# Test class using the mixin
class TestField(RegisterLookupMixin):
    pass


# Test the buggy behavior
print("Testing buggy behavior (without cache clearing):")
TestField.class_lookups = {}  # Reset
TestField.get_lookups.cache_clear()
TestField.register_lookup(DummyLookup)
print(f"  After register: 'test_lookup' in lookups = {'test_lookup' in TestField.get_lookups()}")
TestField._unregister_lookup_buggy(DummyLookup)
print(f"  After unregister (buggy): 'test_lookup' in lookups = {'test_lookup' in TestField.get_lookups()}")
buggy_result = 'test_lookup' in TestField.get_lookups()

# Test the fixed behavior
print("\nTesting fixed behavior (with cache clearing):")
TestField.class_lookups = {}  # Reset
TestField.get_lookups.cache_clear()
TestField.register_lookup(DummyLookup)
print(f"  After register: 'test_lookup' in lookups = {'test_lookup' in TestField.get_lookups()}")
TestField._unregister_lookup_fixed(DummyLookup)
print(f"  After unregister (fixed): 'test_lookup' in lookups = {'test_lookup' in TestField.get_lookups()}")
fixed_result = 'test_lookup' in TestField.get_lookups()

# Summary
print("\n=== Results ===")
